            assert_eq!(
                QueueName::parse(name).map(|n| n.0),
                Ok(name.to_owned()),
                "{name}"
            );
        }
        let rejected = [
            "",
            ".fifo",
            "a.b",
            "a.fifo.fifo",
            "a b",
            "é",
            "jobs\n",
            "a.FIFO",
            too_long.as_str(),
            too_long_fifo.as_str(),
