            parse(r#"{"Command": "CreateQueue", "QueueName": "a b", "Attributes": 5}"#),
            Err(ErrorCode::QueueNameInvalid)
        );
        assert_eq!(
            parse(r#"{"Command": "CreateQueue", "QueueName": 5, "Attributes": 5}"#),
            Err(ErrorCode::InvalidParameterValue)
        );
