        Queue::new(
            QueueId::FIRST,
            &spec(QueueType::Fifo {
                content_based_deduplication,
            }),
            None,
        )
    }

    fn at(seconds: u32) -> Instant {
        Instant::START.plus(Retention::constant(60).min_with(seconds))
    }

