    let responses = run_bytes(b"\n{\"Command\":\"Tick\",\"Seconds\":1}\nnot json\n\xff\n{\"Command\":\"Tick\",\"Seconds\":2}");
    assert_responses(
        responses,
        vec![
            failure("InvalidRequest"),
            json!({"ok": true, "Now": 1}),
            failure("InvalidRequest"),
            failure("InvalidRequest"),
            json!({"ok": true, "Now": 3}),
