        r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"a2","GroupId":"a","DeduplicationId":"2"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q.fifo"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q.fifo"}"#,
